# Safe integer binomial

def comb(n, k):
    if k < 0 or k > n:
        return 0
    k = min(k, n - k)
    num = 1
    den = 1
    for i in range(1, k + 1):
        num *= (n - k + i)
        den *= i
    return num // den


def verifier(assign):
    # Validate keys
    required = {'n', 'a_num', 'a_den', 'm'}
    if not required.issubset(assign.keys()):
        # missing slots
        return (False, None)

    n = assign['n']
    a_num = assign['a_num']
    a_den = assign['a_den']
    m = assign['m']

    # Domain checks
    if not (isinstance(n, int) and n >= 9 and n % 2 == 1):
        # need odd n >= 9
        return (False, None)
    if not (isinstance(a_num, int) and isinstance(a_den, int) and a_den > 0):
        return (False, None)
    # a must be nonzero to avoid zero polynomial
    if a_num == 0:
        return (False, None)
    if m not in (2, 3):
        return (False, None)

    a = Fraction(a_num, a_den)
    N = n - 1  # actual degree after cancellation for odd n

    # Build needed coefficients of P(x) = x^n + (a - x)^n. For k <= N, c_k is from (a - x)^n only.
    # (a - x)^n = sum_{k=0}^n (-1)^k * C(n,k) * a^{n-k} x^k
    # So for k in [0, N]: c_k = (-1)^k * C(n,k) * a^{n-k}

    # We need c_N, c_{N-1}, ..., c_{N-m}
    coeff = {}
    for j in range(0, m + 1):
        k = N - j
        sign = -1 if (k % 2 == 1) else 1
        # (-1)^k
        sign = -1 if k % 2 == 1 else 1
        ck_int = comb(n, k)
        # c_k as Fraction
        coeff[k] = Fraction(sign * ck_int) * (a ** (n - k))

    A = coeff[N]  # leading coefficient of degree N
    # Sanity: for odd n, A should be n*a > 0 if a>0
    # Ensure we truly have degree N (i.e., x^n term cancels)
    if A == 0:
        # would imply deg drop further; invalid for our setup
        return (False, None)

    # Newton sums for non-monic polynomial:
    # For i >= 1: A s_i + c_{N-1} s_{i-1} + c_{N-2} s_{i-2} + ... + i * c_{N-i} = 0
    s = [Fraction(0)] * (m + 1)
    for i in range(1, m + 1):
        acc = Fraction(0)
        for j in range(1, i):
            acc += coeff[N - j] * s[i - j]
        acc += Fraction(i) * coeff[N - i]
        s[i] = -acc / A

    ans = s[m]

    # Nontriviality checks: ensure answer not zero and not tiny
    if ans == 0:
        # avoid trivial sum
        return (False, None)

    # Return integer if possible, else a reduced fraction string
    if ans.denominator == 1:
        return (True, ans.numerator)
    else:
        return (True, f"{ans.numerator}/{ans.denominator}")


